const e={title:"TripReel - 무료 여행 애니메이션 앱: 사진을 아름다운 비디오로 변환",description:"애니메이션 지도와 비행 경로로 멋진 여행 비디오를 만드세요. 3D 글로브 경로 매핑이 있는 무료 여행 애니메이션 앱. 사진을 자동으로 아름다운 여행 비디오로 변환. 프라이버시 우선, 오프라인 작동.",keywords:"여행 애니메이션 앱, 여행 지도 애니메이션 앱, 여행 경로 애니메이션 앱, 비행 애니메이션 앱, 여행 비디오 메이커, 자동 여행 비디오, 애니메이션 여행 지도, 비행 경로 애니메이션, 여행 애니메이션, 글로브 애니메이션, 여행 회고 비디오, 사진에서 비디오로, 여행 하이라이트, 무료 여행 앱, 오프라인 비디오 메이커, 프라이버시 여행 앱, 카메라 롤 비디오"},t={logoAlt:"TripReel 로고",appName:"TripReel",howItWorks:"작동 방식",video:"동영상",features:"기능",theApp:"앱"},i={badge:"사진을 여행 스토리로 변환",title1:"당신의 카메라 롤,",title2:"완전히 활용",description:"TripReel은 사진의 위치 정보에서 자동으로 아름다운 여행 동영상을 만듭니다. 3D 지구본의 멋진 애니메이션 경로 지도와 비행 경로로 여행이 생생하게 살아나는 것을 지켜보세요. 데이터는 항상 비공개이고 안전하게 유지됩니다.",secure:"100% 안전",worksOffline:"오프라인 작동",globeAlt:"TripReel 지구본 애니메이션"},r={title:"작동 방식",subtitle:"완벽한 여행 동영상을 만드는 세 가지 간단한 단계",step1:{title:"사진 접근 허용",description:"TripReel에 사진 라이브러리 접근을 허용하세요. 앱은 위치 메타데이터만 읽습니다."},step2:{title:"자동 여행 감지",description:"TripReel은 위치 메타데이터를 분석하고 날짜와 위치를 기반으로 지능적으로 여행을 찾습니다."},step3:{title:"동영상 생성",description:"아름다운 지구본 애니메이션에서 여행이 펼쳐지는 것을 지켜보세요. 소셜 미디어에 공유할 준비가 됩니다."}},o={title:"마법이 일어나는 것을 보세요",subtitle:"TripReel이 사진 라이브러리를 놀라운 여행 동영상으로 변환하는 방법을 확인하세요",caption:"최종 여행 동영상이 이렇게 보일 수 있습니다"},s={title:"필요한 모든 것",subtitle:"현대 여행자를 위해 설계된 강력한 기능",twoTap:{title:"두 번의 탭으로 여행 동영상",description:"단 두 번의 탭만으로 사진 라이브러리에서 놀라운 여행 동영상을 만드세요. 편집 불필요."},smartTrip:{title:"스마트 여행 감지",description:"사진의 날짜와 위치 메타데이터를 분석하여 자동으로 여행을 찾고 그룹화합니다."},globe:{title:"아름다운 지구본 애니메이션",description:"전 세계의 애니메이션 여행 경로와 비행 경로를 보여주는 멋진 3D 지구본으로 여행이 생생하게 살아납니다."},privacy:{title:"개인정보 보호 우선",description:"모든 것이 기기에서 처리됩니다. 사진은 절대 휴대전화를 떠나지 않습니다. 비행기 모드에서 작동합니다."},customStyles:{title:"맞춤 스타일",description:"여러 지구본 스타일과 사용자 지정 중에서 선택하여 미학에 맞추고 각 동영상을 고유하게 만드세요."},manualControl:{title:"수동 제어",description:"기기에서 위치 서비스가 활성화되지 않은 경우 완전히 새로운 여행을 수동으로 추가할 수 있습니다."}},l={title:"창의적인 동영상 아이디어",subtitle:"TripReel로 만들 수 있는 것에서 영감을 얻으세요. 빠른 주말 여행부터 1년간의 모험까지, 모든 여행을 위한 놀라운 여행 동영상을 만드세요.",description:"여행 지도 애니메이션을 만들거나, 비행 경로를 문서화하거나, 연말 여행 요약을 만들든, TripReel은 추억을 공유 가능한 동영상으로 쉽게 변환합니다.",ideas:{yearRecap:{title:"2025년 여행 요약",description:"2025년 연간 여행 요약 동영상을 자동으로 만드세요"},europeRoadTrip:{title:"유럽 로드트립",description:"애니메이션 경로 지도로 유럽 모험을 선보이세요"},southeastAsia:{title:"동남아시아 여행",description:"여러 국가를 가로지르는 배낭여행 경로를 시각화하세요"},japanRail:{title:"일본 기차 여행",description:"일본 전역의 기차 경로 지도 동영상을 만드세요"},crossCountry:{title:"미국 횡단",description:"미국 로드트립을 장대한 경로 동영상으로 만드세요"},islandHopping:{title:"섬 호핑",description:"멋진 3D 애니메이션으로 섬에서 섬으로의 여행을 보여주세요"},worldTour:{title:"세계 일주 몽타주",description:"여러 여행을 하나의 놀라운 글로벌 여행 동영상으로"},travelPlans:{title:"2026년 여행 계획",description:"2026년의 흥미진진한 여행 모험을 시각화하고 계획하세요"},lifetimeTravel:{title:"평생 여행 이야기",description:"평생의 모든 여행을 보여주는 동영상을 만드세요"},regionalExplorer:{title:"지역 탐험가",description:"주, 지방 및 지역을 가로지르는 모험을 도표화하세요"},festivalCircuit:{title:"페스티벌 서킷",description:"음악 페스티벌 및 이벤트 여행을 지도로 그리세요"},bikeRoutes:{title:"내 도시 여행",description:"모든 도시 여행을 선보이세요"}}},a={title:"앱",subtitle:"App Store에서 지금 사용 가능",alt1:"자동 여행 동영상 - 몇 초 만에 놀라운 동영상 만들기",alt2:"사진 위치 감지 - 사진의 메타데이터 사용",alt3:"여행 감지 - 자동으로 여행 그룹화",alt4:"아름다운 지구본 동영상 - 여행의 지구본 애니메이션",alt5:"맞춤 스타일 - 여행 동영상 개인화"},n={comingSoon:"출시 예정",androidTitle:"Android 앱 출시 예정!",androidMessage:'Android 버전은 아직 사용할 수 없지만 곧 출시됩니다. <a href="mailto:marian@qod.ee?subject=TripReel%20Android%20App" class="text-sky-600 dark:text-sky-400 hover:text-sky-700 dark:hover:text-sky-300 font-semibold transition-colors">marian@qod.ee</a>로 메시지를 보내주시면 준비되면 알려드리겠습니다!',gotIt:"알겠습니다!"},p={title:"자주 묻는 질문",subtitle:"TripReel에 대해 알아야 할 모든 것",q1:{question:"비행기 모드에서 앱을 완전히 사용할 수 있나요?",answer:"예! 프리미엄 사용자의 경우 앱을 비행기 모드에서 제한 없이 완전히 오프라인으로 사용할 수 있습니다. 비프리미엄 사용자의 경우 일부 기능은 광고 지원되며 일시적으로 인터넷을 활성화해야 할 수 있지만, 프리미엄 사용자에게는 광고가 없으며 앱을 비행기 모드에서 완전히 사용할 수 있습니다."},q2:{question:"프리미엄으로 업그레이드했는데 워터마크를 제거하려면 어떻게 하나요?",answer:"많은 사람들이 이 동영상을 만드는 데 사용된 앱이 무엇인지 묻기 때문에 프리미엄으로 업그레이드한 후 워터마크의 작은 버전(앱 이름만 포함)을 추가하거나 원하는 경우 완전히 제거할 수 있는 옵션이 있습니다."},q3:{question:"내 사진 데이터는 안전하고 비공개인가요?",answer:"물론입니다! TripReel은 사진에서 위치 메타데이터만 읽습니다. 실제 사진 내용에 액세스하거나 저장하거나 전송하지 않습니다. 모든 처리는 기기에서 로컬로 수행되며 데이터가 휴대전화를 떠나지 않습니다. 비행기 모드에서 앱을 사용하여 확인할 수 있습니다. 완전히 오프라인으로 작동합니다!"},q4:{question:"내 사진에 위치 데이터가 없으면 어떻게 하나요?",answer:"문제없습니다! 사진을 찍을 때 위치 서비스가 활성화되지 않은 경우 수동으로 여행을 만들고 직접 위치를 추가할 수 있습니다. 앱은 여행 타임라인을 사용자 지정할 수 있는 완전한 제어권을 제공합니다."},q5:{question:"앱이 자동으로 내 여행을 어떻게 감지하나요?",answer:"TripReel은 사진의 위치 메타데이터와 타임스탬프를 분석하여 언제 어디로 여행했는지 지능적으로 식별합니다. 근처 위치와 날짜를 함께 그룹화하여 수동 작업 없이 자동으로 여행을 감지합니다."},q6:{question:"동영상의 모양을 사용자 지정할 수 있나요?",answer:"예! 여러 지구본 스타일 중에서 선택하고 개인 미학에 맞게 애니메이션 여행 동영상의 다양한 측면을 사용자 지정할 수 있습니다. 프리미엄 사용자는 추가 경로 애니메이션 스타일, 지도 테마 및 비행 경로 옵션에 액세스할 수 있습니다."},q7:{question:"계정을 만들어야 하나요?",answer:"계정이 필요하지 않습니다! TripReel은 다운로드 직후 작동합니다. 등록도 로그인도 개인 정보도 필요하지 않습니다. 앱을 다운로드하고 즉시 여행 동영상 만들기를 시작하세요."},q8:{question:"내 여행에서 위치가 누락된 이유는 무엇인가요?",answer:"앱은 사용 가능한 데이터로만 작동할 수 있으므로 먼저 해당 위치에 최소한 몇 장의 사진이 필요합니다. 둘째, 그곳에 있을 때 위치 데이터가 활성화되어 있었는지 확인해야 합니다. 셋째, 때로는 GPS 수신이 약하면 잘못된 위치 데이터가 발생할 수 있습니다. 이 모든 것을 배제했는데도 위치가 표시되지 않으면 여행 개요 > 편집 버튼에서 해당 위치를 수동으로 추가할 수 있습니다. 문제를 보고하려면 연락처도 사용하세요."},q9:{question:"멋진 동영상을 어디에 공유할 수 있나요?",answer:"물론 모든 소셜 플랫폼에서도 공유할 수 있습니다. 플랫폼에 더 잘 맞도록 앱은 동영상에 다양한 종횡비를 허용합니다."},q10:{question:"버그를 어디에 보고할 수 있나요?",answer:"marian@qod.ee로 직접 연락하여 문제가 무엇인지 간략하게 설명하세요."}},d={title:"이메일 지원",description:"피드백이 있거나 문제가 발생하면 이 이메일로 직접 연락 주시면 최대한 빨리 개인적으로 요청을 읽고 처리하겠습니다. 앱을 사용해 주셔서 감사합니다!",close:"닫기"},c={default:{title:"🍪 쿠키",message:"TripReel 사이트에서 쿠키를 사용하여 경험을 향상시킵니다. 개인 데이터는 수집되지 않습니다.",accept:"동의",decline:"거부",details:"세부정보"},theme:{title:"🍪 쿠키",message:"🌙 테마 기본 설정을 저장하려면 TripReel 사이트에서 필수 쿠키를 수락해야 합니다. 쿠키 없이는 테마 선택을 저장할 수 없습니다.",accept:"동의",decline:"거부",details:"세부정보"}},u={privacy:"앱 개인정보 보호정책",cookies:"사이트 쿠키 정책",contact:"연락처",cookiePreferences:"쿠키 기본 설정",madeWith:"제작",forTravelers:"전 세계 여행자를 위한",copyright:"© {{year}} TripReel."},T={title:"여행을 공유할 준비가 되셨나요?",description:"오늘 TripReel을 다운로드하고 카메라 롤을 애니메이션 지도와 경로가 있는 아름다운 여행 동영상으로 변환하세요. 당신의 모험은 축하받을 가치가 있습니다.",features:"무료 다운로드 • 빠르고 편리 • 개인정보 보호 보장"},q={meta:e,header:t,hero:i,howItWorks:r,videoSection:o,features:s,videoIdeas:l,screenshots:a,appStore:n,faq:p,contact:d,cookieBanner:c,footer:u,cta:T};export{n as appStore,d as contact,c as cookieBanner,T as cta,q as default,p as faq,s as features,u as footer,t as header,i as hero,r as howItWorks,e as meta,a as screenshots,l as videoIdeas,o as videoSection};
